CREATE TABLE perf15_stats (record_id INTEGER PRIMARY KEY, category TEXT NOT NULL, amount INTEGER NOT NULL);
INSERT INTO perf15_stats VALUES (1, 'Books', 10), (2, 'Books', 20), (3, 'Games', 30), (4, 'Games', 40), (5, 'Games', 50);
CREATE INDEX idx_perf15_stats_category ON perf15_stats(category);
ANALYZE perf15_stats;
SELECT tbl, idx FROM sqlite_stat1 WHERE tbl = 'perf15_stats' ORDER BY idx;

